template:
fn inspect_label(opt: &Option<String>) -> usize {
    match ⟦scrutinee⟧ {
        ⟦pattern⟧ => s.len(),
        None => 0,
    }
}

fn main() {
    let label = Some(String::from("rust"));
    println!("{}", inspect_label(&label));
    println!("{:?}", label);
}

tests:
#[test]
fn inspects_without_moving() {
    let label = Some(String::from("rustchap"));
    assert_eq!(inspect_label(&label), 8);
    assert_eq!(label, Some(String::from("rustchap")));
    assert_eq!(inspect_label(&None), 0);
}
